-- 示例数据：广州 5 个旅游片区、15 个景点、4 家餐厅。只在第一次启动、片区表为空时导入。
-- 开放时间、门票、地址整理自景点官网、政府网站和官方公众号（2026-09-17 核实），实际以官方公布为准；
-- 街区、广场这类全天开放的地方没有官方开放时间，按一般游览时间填写。
-- 餐厅人均参考大众点评（2026-09-17）。评分是演示用的推荐值，不是第三方平台的评分，可以在后台修改。
-- 坐标为高德坐标系（GCJ-02）。


                 stay_minutes, full_day, ticket_price, avg_cost, rating, tags, status) VALUES
    (1, 'SCENIC', '陈家祠（广东民间工艺博物馆）', 1, '荔湾区', '广州市荔湾区中山七路恩龙里34号', 113.245432, 23.127161, '清光绪十九年（1893年）落成的陈姓合族祠，匾题“陈氏书院”，以砖雕、木雕、灰塑等装饰工艺著称，现为广东民间工艺博物馆馆址。门票 10 元，需在“广东民间工艺博物馆”公众号实名预约；周二闭馆（法定节假日除外）。', 'ancestral-hall', NULL, 90, 0, 10, NULL, 4.7, '历史人文,岭南建筑,博物馆,拍照,适合长辈', 'ONLINE'),
    (2, 'SCENIC', '沙面', 1, '荔湾区', '广州市荔湾区沙面岛（沙面大街一带）', 113.244646, 23.106783, '珠江白鹅潭畔的小岛，近代曾为英法租界，岛上有150多座欧洲风格建筑，其中53座（处）为国家重点文物保护建筑。开放式街区，免费，全天可进入。', 'western-villa', NULL, 120, 0, 0, NULL, 4.6, '历史人文,拍照,室外,适合长辈', 'ONLINE'),
    (3, 'SCENIC', '永庆坊', 1, '荔湾区', '广州市荔湾区恩宁路99号', 113.238228, 23.114823, '西关恩宁路上的历史街区，经微改造保留骑楼和传统民居，集非遗传承、文创商铺于一体，属国家4A级的西关永庆坊旅游区。街区免费开放，商铺营业时间各不相同。', 'arcade-street', NULL, 120, 0, 0, NULL, 4.5, '岭南建筑,历史人文,拍照,美食,购物', 'ONLINE'),
    (4, 'SCENIC', '北京路步行街', 1, '越秀区', '广州市越秀区北京路（步行街段）', 113.269035, 23.123019, '广州自建城以来的传统商业中心和古代中轴线所在，步行街沿线有千年古道遗址、大佛寺等文物，属国家4A级北京路文化旅游区。街区免费，沿街商铺一般营业到 22:00。', 'arcade-street', 'http://www.beijinglu.yuexiu.gov.cn/', 120, 0, 0, NULL, 4.4, '历史人文,购物,美食,夜景,室外', 'ONLINE'),
    (5, 'SCENIC', '越秀公园', 1, '越秀区', '广州市越秀区解放北路988号', 113.265588, 23.140197, '广州市区最大的综合性公园，由七个山岗和三个人工湖组成，园内有五羊石像、中山纪念碑、镇海楼和明城墙等古迹。公园免费；园内镇海楼另收门票 10 元，周一闭馆。', 'city-park', 'https://lyylj.gz.gov.cn/stly/gyjq/yxgy/index.html', 150, 0, 0, NULL, 4.5, '自然风光,历史人文,适合长辈,亲子,室外', 'ONLINE'),
    (6, 'SCENIC', '光孝寺', 1, '越秀区', '广州市越秀区光孝路109号', 113.256382, 23.129418, '广州年代最古、规模最大的佛教寺院之一，有“未有羊城，先有光孝”之说，相传禅宗六祖慧能在此受戒，全国重点文物保护单位。门票 5 元，寺内提倡鲜花供佛、不带香烛。', 'temple', NULL, 60, 0, 5, NULL, 4.6, '宗教文化,历史人文,岭南建筑,适合长辈', 'ONLINE'),
    (7, 'SCENIC', '南越王博物院（王墓展区）', 1, '越秀区', '广州市越秀区解放北路867号', 113.261479, 23.137703, '以西汉南越文王墓原址为核心的遗址博物馆展区，基本陈列为南越王墓原址和“南越藏珍”西汉南越王墓出土文物陈列。门票 10 元，需在“南越王博物院”公众号预约；周一闭馆（法定假日照常开放）。', 'museum', 'https://www.nywmuseum.org.cn/', 90, 0, 10, NULL, 4.8, '博物馆,历史人文,室内,适合长辈', 'ONLINE'),
    (8, 'SCENIC', '广州塔', 2, '海珠区', '广州市海珠区阅江西路222号', 113.324557, 23.106589, '位于城市新中轴线与珠江交汇处的地标观光塔，昵称“小蛮腰”，设428米、433米观光大厅，450米、488米户外平台及横向摩天轮。基础登塔票（433 米观光）150 元，实名分时段登塔；含摩天轮的套票 298 元。', 'canton-tower', 'https://www.cantontower.com/', 120, 0, 150, NULL, 4.7, '城市地标,夜景,拍照,室内', 'ONLINE'),
    (9, 'SCENIC', '花城广场', 2, '天河区', '广州市天河区珠江新城（珠江西路以东、珠江东路以西、黄埔大道以南、临江大道以北）', 113.324662, 23.123618, '珠江新城城市新中轴线上的大型广场，周边有广州大剧院、广东省博物馆和广州图书馆，与广州塔隔江相望，是看夜景的热门地点。开放式广场，免费。', 'river-night', NULL, 60, 0, 0, NULL, 4.5, '城市地标,夜景,拍照,室外', 'ONLINE'),
    (10, 'SCENIC', '广东省博物馆', 2, '天河区', '广州市天河区珠江新城珠江东路2号', 113.326802, 23.114611, '广东省级综合性博物馆、国家一级博物馆，珠江新城馆区免费开放，实行全员分时段实名预约参观。免费开放，需在官方公众号分时段实名预约；周一闭馆（法定节假日除外）。', 'museum', 'https://www.gdmuseum.org.cn/', 180, 0, 0, NULL, 4.8, '博物馆,历史人文,亲子,室内,适合长辈', 'ONLINE'),
    (11, 'SCENIC', '海珠国家湿地公园', 3, '海珠区', '广州市海珠区新滘中路168号（湿地一期，售票处在北门）', 113.340110, 23.078327, '位于广州中心城区的国家湿地公园，总面积约1100公顷，由海珠湖和果林、河涌湿地组成，2023年列入国际重要湿地名录。湿地一期、二期门票 20 元，海珠湖园区免费；一期、二期周一闭园。', 'water-town', NULL, 180, 0, 20, NULL, 4.5, '自然风光,亲子,拍照,室外,适合长辈', 'ONLINE'),
    (12, 'SCENIC', '白云山', 4, '白云区', '广州市白云区广园中路801号', 113.296656, 23.160469, '广州北部的国家5A级风景名胜区，由三十多座山峰组成，最高峰摩星岭海拔382米，有云台花园、能仁寺、山顶广场等景点。进山门票 5 元，园中园和索道另收费；各门岗开放时间不同。', 'mountain', 'https://www.baiyunshan.com.cn/', 240, 0, 5, NULL, 4.6, '自然风光,室外,适合长辈,拍照', 'ONLINE'),
    (13, 'SCENIC', '长隆野生动物世界', 5, '番禺区', '广州市番禺区汉溪大道东299号', 113.314689, 23.002637, '1997年开园的野生动物主题公园，以大规模动物种群放养和自驾车、小火车、缆车观赏为特色，保育500余种、两万余只野生动物。平日门票 300 元、特定日 350 元，实名购票；营业时间官网按月公布。', 'safari', 'https://www.chimelong.com/gz/safaripark/', 480, 1, 300, NULL, 4.8, '动物,亲子,室外', 'ONLINE'),
    (14, 'SCENIC', '余荫山房', 5, '番禺区', '广州市番禺区南村镇北大街', 113.395629, 23.011185, '清同治年间（1867—1871年）建成的私家园林，与梁园、可园、清晖园合称广东四大名园，全国重点文物保护单位。门票 18 元，17:00 停止售票和入园。', 'water-town', 'https://www.yuyinshanfang.com/', 90, 0, 18, NULL, 4.6, '岭南建筑,历史人文,拍照,适合长辈', 'ONLINE'),
    (15, 'SCENIC', '沙湾古镇', 5, '番禺区', '广州市番禺区沙湾街大巷涌路64号（沙湾古镇南门游客中心）', 113.337531, 22.901895, '始建于南宋的中国历史文化名镇，保存以留耕堂为代表的百余座古祠堂和大量明清建筑，被评为“广东音乐之乡”。古镇街巷免费；留耕堂等七个展馆需购联票 40 元。', 'ancestral-hall', 'http://www.shawanguzhen.com/', 150, 0, 40, NULL, 4.4, '岭南建筑,历史人文,美食,拍照,室外', 'ONLINE'),
    (16, 'RESTAURANT', '广州酒家（文昌总店）', 1, '荔湾区', '广州市荔湾区文昌南路2号', 113.245928, 23.113813, '1935年开业的广州酒家发源地（前身西南酒家），中华老字号，以传统广府粤菜和点心为主，店内保留中庭天井、鱼池水榭。', 'dim-sum', 'https://www.gzr.com.cn/', 60, 0, NULL, 109, 4.5, '早茶,粤菜,老字号,适合长辈', 'ONLINE'),
    (17, 'RESTAURANT', '北园酒家', 1, '越秀区', '广州市越秀区小北路200-202号', 113.272445, 23.136488, '创建于1928年的园林式粤菜酒家，中华老字号，店内有鱼池石山、小桥流水、曲径回廊等岭南庭院景致。', 'dim-sum', NULL, 60, 0, NULL, 189, 4.4, '粤菜,老字号,园林,早茶,适合长辈', 'ONLINE'),
    (18, 'RESTAURANT', '炳胜品味（珠江新城旗舰店）', 2, '天河区', '广州市天河区珠江新城冼村路2号1-4楼（广东省博物馆对面）', 113.328383, 23.114979, '炳胜饮食集团旗下粤菜酒楼的珠江新城旗舰店，位于广东省博物馆对面，集团招牌出品包括烧味、鱼生等系列。', 'dim-sum', 'https://www.bingsheng.com/', 60, 0, NULL, 129, 4.5, '粤菜,适合长辈,亲子', 'ONLINE'),
    (19, 'RESTAURANT', '山庄旅舍陶然餐厅', 4, '白云区', '广州市白云区白云山风景名胜区云山中路13号（广州山庄旅舍内）', 113.303685, 23.179540, '位于白云山景区内山庄旅舍（1965年建，莫伯治、吴威亮设计）的粤菜餐厅，白云猪手、自磨豆腐花等菜式以泉水烹煮。', 'dim-sum', NULL, 60, 0, NULL, 171, 4.3, '粤菜,园林,适合长辈', 'ONLINE');

